preConditionHook:
// EL:
//   recentSpan = highest(h, flagBars) - lowest(l, flagBars);
//   priorSpan  = highest(h, flagBars)[flagBars] - lowest(l, flagBars)[flagBars];
// written lowercase as the feature register does.
// The recent window INCLUDES the current bar (bars 0..flagBars-1); the prior
// window is the same window shifted back by its own length (bars
// flagBars..2*flagBars-1), which is what the [flagBars] offset on a Highest
// means.
//
// highest/lowest bottom out in Extremes(), which is EL SOURCE: seeded at the
// first bar of its window, scanning the rest with a strict, tolerance-carrying
// comparison, so a tie keeps the earliest bar. Written out with el_gt/el_lt as
// Breakout does.
//
// Every scratch value is a declared local, not a hook-scope declaration, so a
// second placement of this rule gets its own prefixed copy.
recentHigh = high[0];
recentLow = low[0];
for (int i = 1; i < (int)flagBars; ++i) {
    if (el_gt(high[i], recentHigh)) recentHigh = high[i];
    if (el_lt(low[i], recentLow)) recentLow = low[i];
}
priorHigh = high[(int)flagBars];
priorLow = low[(int)flagBars];
for (int i = (int)flagBars + 1; i < 2 * (int)flagBars; ++i) {
    if (el_gt(high[i], priorHigh)) priorHigh = high[i];
    if (el_lt(low[i], priorLow)) priorLow = low[i];
}
recentSpan = recentHigh - recentLow;
priorSpan = priorHigh - priorLow;
